{
  "verdict": "CHANGES",
  "findings": [
    {
      "scope": "SPEC",
      "severity": "medium",
      "reference": "Task Card lines 1–3",
      "problem": "The acceptance matrix leaves the expected outputs implicit and omits the below-minimum and nonpositive-step rejection cases. It also does not require an off-grid broker maximum, so an above-maximum test can miss a rounding overshoot.",
      "example": "For minVolume=0.25, maxVolume=1.125, and step=0.25, require request 0.75 → 0.75, 0.875 → 0.75, 2.0 → 1.0, and 0.125 → 0. Separately, require request 0.75 → 0 with step=0 and step=-0.25."
    },
    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "QuantizeVolume below-minimum branch",
      "problem": "Returning minVolume for a below-minimum request replaces the rejection sentinel with a volume larger than requested. A caller can treat that result as a valid volume and take on more exposure than requested.",
      "example": "With request=0.125, minVolume=0.25, maxVolume=1.0, and step=0.25, the new code returns 0.25. The expected result is 0."
    },
    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "QuantizeVolume rounding expression",
      "problem": "MathCeil rounds the capped volume up to the next grid point. This can exceed the requested volume or the broker maximum. Restore downward rounding.",
      "example": "With minVolume=0.25, maxVolume=1.125, and step=0.25, request=0.875 returns 1.0 instead of 0.75, and request=2.0 returns 1.25 instead of 1.0."
    },
    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "QuantizeVolume step validation",
      "problem": "Removing the step <= 0 guard allows division by zero and lets negative steps enter the grid calculation. Restore the zero-sentinel return for nonpositive steps.",
      "example": "With request=0.75, minVolume=0.25, and maxVolume=1.0, both step=0 and step=-0.25 must return 0 before the division."
    }
  ]
}
